<?php use backend\models\LectureClassSchedule;use yii\helpers\Html;$days=LectureClassSchedule::dayOptions();$rows=[];foreach($classes as $class)foreach($class->schedules as $schedule)$rows[]=['day'=>$schedule->weekday,'class'=>$class,'schedule'=>$schedule];usort($rows,static fn($a,$b)=>$a['day']<=>$b['day']);?>
